import sys
from pathlib import Path
import numpy as np
for _p in (Path(__file__).resolve().parent, Path.cwd()):
    if (_p / 'source').exists() and str(_p / 'source') not in sys.path:
        sys.path.insert(0, str(_p / 'source'))
from desc.stability.terpsichore.demo_case import build_demo_case
from desc.stability.terpsichore.equilibrium import vacmet_inputs_from_equilibrium_data
from desc.stability.terpsichore.vacuum import compute_vacmet_metrics

case = build_demo_case()
eq = case['equilibrium_data']
base = vacmet_inputs_from_equilibrium_data(eq, wall=None, wall_scale=1.0, nowall=1)
b = {k: base[k] for k in ('rpvi', 'vpvi', 'zpvi', 'rtpvi', 'ztpvi', 'rppvi', 'zppvi')}
def wall(s):
    return {'rwall': s * b['rpvi'], 'zwall': b['zpvi'].copy(), 'rtwall': s * b['rtpvi'],
            'ztwall': b['ztpvi'].copy(), 'rpwall': s * b['rppvi'], 'zpwall': b['zppvi'].copy()}
m1 = compute_vacmet_metrics(**vacmet_inputs_from_equilibrium_data(eq, wall=wall(1.3), wall_scale=1.0, nowall=1))
m2 = compute_vacmet_metrics(**vacmet_inputs_from_equilibrium_data(eq, wall=wall(1.8), wall_scale=1.0, nowall=1))
d = max(float(np.max(np.abs(getattr(m1, n) - getattr(m2, n))))
        for n in ('bjac', 'gppl', 'gtpl', 'gttl', 'gssu', 'gstl', 'gssl'))
ok = bool(d > 1e-12)
print('PASS' if ok else 'FAIL')
